+// Generated by offramp service from Heartbeat.HeartbeatService. Review the regions marked OFR4102, then own this file.
+using System;
+using System.Configuration;
+using System.Diagnostics;
+using System.Timers;
+
+namespace Heartbeat
+{
+    /// <summary>Records a beat every few seconds.</summary>
+    public sealed class HeartbeatWorker : Microsoft.Extensions.Hosting.BackgroundService
+    {
+        private readonly Microsoft.Extensions.Logging.ILogger<HeartbeatWorker> _workerLogger;
+
+        private readonly Heartbeat.WorkerHeartbeat _workerHeartbeat;
+
+        private readonly Pulse _pulse = new Pulse();
+
+        private bool _paused;
+
+        public HeartbeatWorker(Microsoft.Extensions.Logging.ILogger<HeartbeatWorker> logger, Heartbeat.WorkerHeartbeat heartbeat)
+        {
+            _workerLogger = logger;
+            _workerHeartbeat = heartbeat;
+        }
+
+        private void OnStart(string[] args)
+        {
+            _pulse.Reset(ConfigurationManager.AppSettings["Source"] ?? "heartbeat");
+            Log(Microsoft.Extensions.Logging.LogLevel.Information, "Heartbeat started.");
+        }
+
+        private void OnStop()
+        {
+#if OFFRAMP_SERVICEBASE // OFR4102: ServiceBase.RequestAdditionalTime has no equivalent in the host; review.
+            RequestAdditionalTime(2000);
+#endif
+            _pulse.Flush();
+            Log(Microsoft.Extensions.Logging.LogLevel.Warning, "Heartbeat stopped after " + _pulse.Count + " beats.");
+        }
+
+        private void OnPause()
+        {
+            _paused = true;
+        }
+
+        private void OnContinue()
+        {
+            _paused = false;
+        }
+
+        private void OnElapsed(object sender, ElapsedEventArgs e)
+        {
+            if (_paused)
+            {
+                return;
+            }
+
+            _pulse.Beat(DateTime.UtcNow);
+            Trace.WriteLine("beat " + _pulse.Count);
+        }
+
+        /// <summary>
+        /// The host has no pause or continue (OFR4101): nothing calls <see cref="Pause"/> or
+        /// <see cref="Continue"/> unless the application does. While paused, timer ticks are skipped.
+        /// </summary>
+        public bool Paused { get; private set; }
+
+        public void Pause()
+        {
+            Paused = true;
+            OnPause();
+        }
+
+        public void Continue()
+        {
+            Paused = false;
+            OnContinue();
+        }
+
+        protected override async System.Threading.Tasks.Task ExecuteAsync(System.Threading.CancellationToken stoppingToken)
+        {
+            // OnStart runs off the host's startup path, as it did under the service control manager.
+            await System.Threading.Tasks.Task.Yield();
+            OnStart(System.Array.Empty<string>());
+            _workerHeartbeat.Beat("HeartbeatWorker");
+            try
+            {
+                await EveryAsync(System.TimeSpan.FromMilliseconds(5000), () => OnElapsed(null, null), stoppingToken);
+            }
+            catch (System.OperationCanceledException) when (stoppingToken.IsCancellationRequested)
+            {
+            }
+        }
+
+        public override async System.Threading.Tasks.Task StopAsync(System.Threading.CancellationToken cancellationToken)
+        {
+            // Stop the ticks first, then run OnStop.
+            await base.StopAsync(cancellationToken);
+            OnStop();
+        }
+
+        /// <summary>
+        /// A converted System.Timers.Timer: runs <paramref name="tick"/> every <paramref name="interval"/> until
+        /// the host stops. A failing tick is logged and the next one runs, as with the timer.
+        /// </summary>
+        private async System.Threading.Tasks.Task EveryAsync(System.TimeSpan interval, System.Action tick, System.Threading.CancellationToken stoppingToken)
+        {
+            using (var timer = new System.Threading.PeriodicTimer(interval))
+            {
+                while (await timer.WaitForNextTickAsync(stoppingToken))
+                {
+                    if (Paused)
+                    {
+                        continue;
+                    }
+
+                    try
+                    {
+                        tick();
+                    }
+                    catch (System.Exception exception)
+                    {
+                        Microsoft.Extensions.Logging.LoggerExtensions.LogError(_workerLogger, exception, "A timer tick failed.");
+                    }
+
+                    _workerHeartbeat.Beat("HeartbeatWorker");
+                }
+            }
+        }
+
+        private void Log(Microsoft.Extensions.Logging.LogLevel level, string message)
+        {
+            Microsoft.Extensions.Logging.LoggerExtensions.Log(_workerLogger, level, "{Message}", message);
+        }
+    }
+}
