+// Generated by offramp service from Heartbeat.JanitorService. Review the regions marked OFR4102, then own this file.
+using System;
+using System.Threading;
+
+namespace Heartbeat
+{
+    /// <summary>Sweeps once a minute and reacts to logons: a second service in the same executable.</summary>
+    public sealed class JanitorWorker : Microsoft.Extensions.Hosting.BackgroundService
+    {
+        private readonly Microsoft.Extensions.Logging.ILogger<JanitorWorker> _workerLogger;
+
+        private readonly Heartbeat.WorkerHeartbeat _workerHeartbeat;
+
+        private Timer _sweep;
+
+        public JanitorWorker(Microsoft.Extensions.Logging.ILogger<JanitorWorker> logger, Heartbeat.WorkerHeartbeat heartbeat)
+        {
+            _workerLogger = logger;
+            _workerHeartbeat = heartbeat;
+        }
+
+        private void OnStart(string[] args)
+        {
+            _sweep = new Timer(_ => Sweep(), null, TimeSpan.Zero, TimeSpan.FromMinutes(1));
+        }
+
+        private void OnStop()
+        {
+            _sweep.Dispose();
+        }
+
+#if OFFRAMP_SERVICEBASE // OFR4105: the host does not deliver session changes; review.
+        protected override void OnSessionChange(SessionChangeDescription changeDescription)
+        {
+            if (changeDescription.Reason == SessionChangeReason.SessionLogon)
+            {
+                Sweep();
+            }
+        }
+#endif
+
+        private static void Sweep()
+        {
+            Console.WriteLine("swept at " + DateTime.UtcNow.ToString("O"));
+        }
+
+        protected override async System.Threading.Tasks.Task ExecuteAsync(System.Threading.CancellationToken stoppingToken)
+        {
+            // OnStart runs off the host's startup path, as it did under the service control manager.
+            await System.Threading.Tasks.Task.Yield();
+            OnStart(System.Array.Empty<string>());
+            try
+            {
+                // Nothing ticks here, so the health check hears from the worker every ten seconds while it runs.
+                while (true)
+                {
+                    _workerHeartbeat.Beat("JanitorWorker");
+                    await System.Threading.Tasks.Task.Delay(System.TimeSpan.FromSeconds(10), stoppingToken);
+                }
+            }
+            catch (System.OperationCanceledException) when (stoppingToken.IsCancellationRequested)
+            {
+            }
+        }
+
+        public override async System.Threading.Tasks.Task StopAsync(System.Threading.CancellationToken cancellationToken)
+        {
+            // Stop the ticks first, then run OnStop.
+            await base.StopAsync(cancellationToken);
+            OnStop();
+        }
+    }
+}
