+// Generated by offramp service: the host that runs the workers.
+using System;
+using Microsoft.Extensions.Configuration;
+using Microsoft.Extensions.DependencyInjection;
+using Microsoft.Extensions.Hosting;
+using Microsoft.Extensions.Logging;
+using Microsoft.AspNetCore.Builder;
+using Microsoft.AspNetCore.Hosting;
+using Microsoft.AspNetCore.Http;
+
+var builder = WebApplication.CreateBuilder(args);
+builder.Logging.ClearProviders();
+builder.Logging.AddJsonConsole();
+
+// Containers and systemd stop the process with SIGTERM and kill it after a grace period
+// (Kubernetes: terminationGracePeriodSeconds, 30 by default); keep the shutdown timeout below it.
+builder.Services.Configure<HostOptions>(options =>
+    options.ShutdownTimeout = TimeSpan.FromSeconds(builder.Configuration.GetValue("HostOptions:ShutdownTimeoutSeconds", 25)));
+builder.Services.AddWindowsService(options => options.ServiceName = "Heartbeat");
+builder.Services.AddSystemd();
+builder.Services.AddSingleton(new Heartbeat.WorkerHeartbeat(TimeSpan.FromSeconds(builder.Configuration.GetValue("Health:StaleAfterSeconds", 60)), "HeartbeatWorker", "JanitorWorker"));
+builder.Services.AddHostedService<Heartbeat.HeartbeatWorker>();
+builder.Services.AddHostedService<Heartbeat.JanitorWorker>();
+
+// The health endpoint: 200 while every worker has checked in recently, 503 otherwise.
+builder.WebHost.UseUrls("http://+:" + builder.Configuration.GetValue("Health:Port", 8080).ToString(System.Globalization.CultureInfo.InvariantCulture));
+var app = builder.Build();
+app.MapGet("/health", (Heartbeat.WorkerHeartbeat heartbeat) =>
+{
+    var report = heartbeat.Report(DateTimeOffset.UtcNow);
+    return report.Healthy ? Results.Ok(report) : Results.Json(report, statusCode: StatusCodes.Status503ServiceUnavailable);
+});
+app.Run();
