+# Generated by offramp service: Heartbeat.Worker on Linux nodes.
+apiVersion: v1
+kind: ConfigMap
+metadata:
+  name: heartbeat-worker
+data:
+  DOTNET_ENVIRONMENT: Production
+  HostOptions__ShutdownTimeoutSeconds: "25"
+---
+apiVersion: apps/v1
+kind: Deployment
+metadata:
+  name: heartbeat-worker
+  labels:
+    app: heartbeat-worker
+spec:
+  replicas: 1
+  selector:
+    matchLabels:
+      app: heartbeat-worker
+  template:
+    metadata:
+      labels:
+        app: heartbeat-worker
+    spec:
+      nodeSelector:
+        kubernetes.io/os: linux
+      # Longer than HostOptions:ShutdownTimeoutSeconds, so the workers finish stopping.
+      terminationGracePeriodSeconds: 30
+      containers:
+        - name: worker
+          image: heartbeat-worker:latest
+          envFrom:
+            - configMapRef:
+                name: heartbeat-worker
+          resources:
+            requests:
+              cpu: 100m
+              memory: 128Mi
+            limits:
+              memory: 512Mi
+            ports:
+              - containerPort: 8080
+            livenessProbe:
